<?php

declare(strict_types=1);

namespace Moves\Services\Talk;

use Moves\Boot\Connection;
use PDO;

final class TalkService
{
    private function notifications(): TalkNotificationService { return new TalkNotificationService(); }

    public function dashboard(): array { $pdo=Connection::getInstance(); return ['counts'=>['queued'=>$this->count($pdo,"SELECT COUNT(*) FROM talk_tickets WHERE status='queued'"),'active'=>$this->count($pdo,"SELECT COUNT(*) FROM talk_tickets WHERE status IN ('assigned','open')"),'closed_today'=>$this->count($pdo,"SELECT COUNT(*) FROM talk_tickets WHERE status='closed' AND DATE(closed_at)=CURRENT_DATE"),'contacts'=>$this->count($pdo,'SELECT COUNT(*) FROM talk_contacts')],'queue'=>$this->queue()]; }
    public function queue(): array { return Connection::getInstance()->query("SELECT t.id,t.protocol,t.subject,t.priority,t.status,t.queued_at,t.created_at,t.sla_due_at,c.name contact_name,c.phone contact_phone,q.name queue_name,u.name assigned_name,cv.channel FROM talk_tickets t INNER JOIN talk_conversations cv ON cv.id=t.conversation_id INNER JOIN talk_contacts c ON c.id=cv.contact_id LEFT JOIN talk_queues q ON q.id=t.queue_id LEFT JOIN users u ON u.id=t.assigned_user_id WHERE t.status='queued' ORDER BY FIELD(t.priority,'urgent','high','normal','low'),COALESCE(t.queued_at,t.created_at),t.id LIMIT 100")->fetchAll(PDO::FETCH_ASSOC); }
    public function queueForUser(int $userId): array
    {
        $tenantId=$this->tenantId($userId);
        if ($this->canManage($userId)) {
            $s=Connection::getInstance()->prepare("SELECT t.id,t.protocol,t.subject,t.priority,t.status,t.queued_at,t.created_at,t.sla_due_at,c.name contact_name,c.phone contact_phone,q.name queue_name,u.name assigned_name,cv.channel FROM talk_tickets t INNER JOIN talk_conversations cv ON cv.id=t.conversation_id INNER JOIN talk_contacts c ON c.id=cv.contact_id LEFT JOIN talk_queues q ON q.id=t.queue_id LEFT JOIN users u ON u.id=t.assigned_user_id WHERE t.tenant_id=:tenant_id AND t.status='queued' ORDER BY FIELD(t.priority,'urgent','high','normal','low'),COALESCE(t.queued_at,t.created_at),t.id LIMIT 100");
            $s->execute(['tenant_id'=>$tenantId]);return $s->fetchAll(PDO::FETCH_ASSOC);
        }
        $s=Connection::getInstance()->prepare("SELECT t.id,t.protocol,t.subject,t.priority,t.status,t.queued_at,t.created_at,t.sla_due_at,c.name contact_name,c.phone contact_phone,q.name queue_name,u.name assigned_name,cv.channel FROM talk_tickets t INNER JOIN talk_conversations cv ON cv.id=t.conversation_id INNER JOIN talk_contacts c ON c.id=cv.contact_id INNER JOIN talk_queue_members qm ON qm.queue_id=t.queue_id AND qm.user_id=:user_id AND qm.status='active' LEFT JOIN talk_queues q ON q.id=t.queue_id LEFT JOIN users u ON u.id=t.assigned_user_id WHERE t.tenant_id=:tenant_id AND t.status='queued' ORDER BY FIELD(t.priority,'urgent','high','normal','low'),COALESCE(t.queued_at,t.created_at),t.id LIMIT 100");
        $s->execute(['user_id'=>$userId,'tenant_id'=>$tenantId]);
        return $s->fetchAll(PDO::FETCH_ASSOC);
    }
    public function heartbeat(int $userId): void { Connection::getInstance()->prepare("INSERT INTO talk_presence(user_id,status,last_seen_at) VALUES(:user_id,'online',NOW()) ON DUPLICATE KEY UPDATE status='online',last_seen_at=NOW()")->execute(['user_id'=>$userId]); }
    public function permissions(int $userId): array { $s=Connection::getInstance()->prepare("SELECT COALESCE(tus.talk_role,IF(u.role='admin','admin','agent')) talk_role,COALESCE(tus.max_active_tickets,5) max_active_tickets FROM users u LEFT JOIN talk_user_settings tus ON tus.user_id=u.id WHERE u.id=:id");$s->execute(['id'=>$userId]);return $s->fetch(PDO::FETCH_ASSOC)?:['talk_role'=>'agent','max_active_tickets'=>5]; }
    public function canManage(int $userId): bool { return in_array((string)($this->permissions($userId)['talk_role']??'agent'),['supervisor','admin'],true); }
    private function tenantId(int $userId): int { return (new TalkTenantContext())->id($userId); }
    public function canOperateTicket(int $ticketId,int $userId): bool
    {
        $tenantId=$this->tenantId($userId);
        if($this->canManage($userId)){$s=Connection::getInstance()->prepare("SELECT COUNT(*) FROM talk_tickets WHERE id=:id AND tenant_id=:tenant_id");$s->execute(['id'=>$ticketId,'tenant_id'=>$tenantId]);return (int)$s->fetchColumn()>0;}
        $s=Connection::getInstance()->prepare("SELECT COUNT(*) FROM talk_tickets WHERE id=:id AND tenant_id=:tenant_id AND assigned_user_id=:user_id AND status IN ('assigned','open')");
        $s->execute(['id'=>$ticketId,'tenant_id'=>$tenantId,'user_id'=>$userId]);
        return (int)$s->fetchColumn()>0;
    }
    public function canViewTicket(int $ticketId,int $userId): bool { $tenantId=$this->tenantId($userId);if($this->canManage($userId)){$s=Connection::getInstance()->prepare("SELECT COUNT(*) FROM talk_tickets WHERE id=:id AND tenant_id=:tenant_id");$s->execute(['id'=>$ticketId,'tenant_id'=>$tenantId]);return (int)$s->fetchColumn()>0;}$s=Connection::getInstance()->prepare("SELECT COUNT(*) FROM talk_tickets t LEFT JOIN talk_queue_members qm ON qm.queue_id=t.queue_id AND qm.user_id=:user_id AND qm.status='active' WHERE t.id=:id AND t.tenant_id=:tenant_id AND (t.assigned_user_id=:user_id OR (t.status='queued' AND qm.user_id IS NOT NULL))");$s->execute(['user_id'=>$userId,'id'=>$ticketId,'tenant_id'=>$tenantId]);return (int)$s->fetchColumn()>0; }
    public function saveUserSettings(int $targetUserId,string $role,int $capacity): void { if(!in_array($role,['agent','supervisor','admin'],true))$role='agent';$capacity=max(1,min(100,$capacity));Connection::getInstance()->prepare("INSERT INTO talk_user_settings(user_id,talk_role,max_active_tickets) VALUES(:user_id,:role,:capacity) ON DUPLICATE KEY UPDATE talk_role=VALUES(talk_role),max_active_tickets=VALUES(max_active_tickets)")->execute(['user_id'=>$targetUserId,'role'=>$role,'capacity'=>$capacity]); }
    public function saveQueue(int $id,string $name,?int $departmentId,int $seconds,string $status): int { $name=trim($name);if($name==='')throw new \RuntimeException('Informe o nome da fila.');$status=in_array($status,['active','inactive'],true)?$status:'active';$seconds=max(5,min(86400,$seconds));$slug=$this->slug($name);$pdo=Connection::getInstance();if($id>0){$s=$pdo->prepare("UPDATE talk_queues SET name=:name,department_id=:department_id,auto_assign_after_seconds=:seconds,status=:status WHERE id=:id");$s->execute(['name'=>$name,'department_id'=>$departmentId,'seconds'=>$seconds,'status'=>$status,'id'=>$id]);return $id;}$base=$slug;$n=2;while($this->queueSlugExists($slug))$slug=$base.'-'.$n++;$s=$pdo->prepare("INSERT INTO talk_queues(department_id,name,slug,status,auto_assign_after_seconds) VALUES(:department_id,:name,:slug,:status,:seconds)");$s->execute(['department_id'=>$departmentId,'name'=>$name,'slug'=>$slug,'status'=>$status,'seconds'=>$seconds]);return (int)$pdo->lastInsertId(); }
    public function saveDepartment(int $id,string $name,string $status): int { $name=trim($name);if($name==='')throw new \RuntimeException('Informe o nome do departamento.');$status=in_array($status,['active','inactive'],true)?$status:'active';$pdo=Connection::getInstance();$slug=$this->slug($name);if($id>0){$pdo->prepare("UPDATE talk_departments SET name=:name,status=:status WHERE id=:id")->execute(['name'=>$name,'status'=>$status,'id'=>$id]);return $id;}$base=$slug;$n=2;while((int)$pdo->query("SELECT COUNT(*) FROM talk_departments WHERE slug=".$pdo->quote($slug))->fetchColumn()>0)$slug=$base.'-'.$n++;$s=$pdo->prepare("INSERT INTO talk_departments(name,slug,status) VALUES(:name,:slug,:status)");$s->execute(['name'=>$name,'slug'=>$slug,'status'=>$status]);return (int)$pdo->lastInsertId(); }
    public function departments(): array { return Connection::getInstance()->query("SELECT id,name,slug,status FROM talk_departments ORDER BY name")->fetchAll(PDO::FETCH_ASSOC); }
    public function queueMembers(int $queueId): array { $s=Connection::getInstance()->prepare("SELECT qm.queue_id,qm.user_id,qm.role,qm.capacity,qm.status,u.name,u.email FROM talk_queue_members qm INNER JOIN users u ON u.id=qm.user_id WHERE qm.queue_id=:id ORDER BY u.name");$s->execute(['id'=>$queueId]);return $s->fetchAll(PDO::FETCH_ASSOC); }
    public function saveQueueMember(int $queueId,int $userId,string $role,int $capacity,string $status): void { if(!in_array($role,['agent','supervisor'],true))$role='agent';$status=in_array($status,['active','inactive'],true)?$status:'active';$capacity=max(1,min(100,$capacity));Connection::getInstance()->prepare("INSERT INTO talk_queue_members(queue_id,user_id,role,capacity,status) VALUES(:queue_id,:user_id,:role,:capacity,:status) ON DUPLICATE KEY UPDATE role=VALUES(role),capacity=VALUES(capacity),status=VALUES(status)")->execute(['queue_id'=>$queueId,'user_id'=>$userId,'role'=>$role,'capacity'=>$capacity,'status'=>$status]); }
    public function removeQueueMember(int $queueId,int $userId): void { Connection::getInstance()->prepare("DELETE FROM talk_queue_members WHERE queue_id=:queue_id AND user_id=:user_id")->execute(['queue_id'=>$queueId,'user_id'=>$userId]); }
    private function slug(string $value): string { $value=iconv('UTF-8','ASCII//TRANSLIT//IGNORE',$value)?:$value;$value=strtolower(trim((string)preg_replace('/[^a-zA-Z0-9]+/','-',$value),'-'));return $value!==''?$value:'fila'; }
    private function queueSlugExists(string $slug): bool { $s=Connection::getInstance()->prepare("SELECT COUNT(*) FROM talk_queues WHERE slug=:slug");$s->execute(['slug'=>$slug]);return (int)$s->fetchColumn()>0; }

    public function claim(int $ticketId,int $userId): bool { $pdo=Connection::getInstance();$pdo->beginTransaction();try{$permissions=$this->permissions($userId);$active=$pdo->prepare("SELECT COUNT(*) FROM talk_tickets WHERE assigned_user_id=:user_id AND status IN ('assigned','open')");$active->execute(['user_id'=>$userId]);if((int)$active->fetchColumn()>=(int)$permissions['max_active_tickets']){$pdo->rollBack();return false;}$s=$pdo->prepare("SELECT id,queue_id,status FROM talk_tickets WHERE id=:id FOR UPDATE");$s->execute(['id'=>$ticketId]);$ticket=$s->fetch(PDO::FETCH_ASSOC);if(!$ticket||$ticket['status']!=='queued'){$pdo->rollBack();return false;}if($ticket['queue_id']!==null){$e=$pdo->prepare("SELECT COUNT(*) FROM talk_queue_members WHERE queue_id=:queue_id AND user_id=:user_id AND status='active'");$e->execute(['queue_id'=>$ticket['queue_id'],'user_id'=>$userId]);if((int)$e->fetchColumn()===0){$pdo->rollBack();return false;}}$u=$pdo->prepare("UPDATE talk_tickets SET assigned_user_id=:user_id,status='assigned',assigned_at=NOW(),last_activity_at=NOW(),updated_at=NOW() WHERE id=:id AND status='queued'");$u->execute(['user_id'=>$userId,'id'=>$ticketId]);if($u->rowCount()!==1){$pdo->rollBack();return false;}$pdo->prepare("INSERT INTO talk_events(ticket_id,user_id,actor_type,event_type,payload) VALUES(:ticket_id,:user_id,'user','ticket.claimed',:payload)")->execute(['ticket_id'=>$ticketId,'user_id'=>$userId,'payload'=>json_encode(['assigned_user_id'=>$userId],JSON_THROW_ON_ERROR)]);
            $jack=$pdo->prepare("SELECT summary FROM talk_jack_interactions WHERE ticket_id=:ticket_id AND action='jack.reply' ORDER BY id DESC LIMIT 1");$jack->execute(['ticket_id'=>$ticketId]);$jackSummary=$jack->fetchColumn();
            if(is_string($jackSummary)&&$jackSummary!==''){$pdo->prepare("INSERT INTO talk_jack_interactions(ticket_id,message_id,action,summary,payload) VALUES(:ticket_id,NULL,'jack.handoff',:summary,:payload)")->execute(['ticket_id'=>$ticketId,'summary'=>mb_substr($jackSummary,0,1000),'payload'=>json_encode(['assigned_user_id'=>$userId,'preserved_context'=>true],JSON_THROW_ON_ERROR)]);}
            $pdo->commit();return true;}catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;} }

    public function seedSimulation(int $actorId): int { $pdo=Connection::getInstance();$pdo->beginTransaction();try{$pdo->exec("INSERT IGNORE INTO talk_departments(name,slug,status) VALUES('Atendimento','atendimento','active')");$departmentId=(int)$pdo->query("SELECT id FROM talk_departments WHERE slug='atendimento'")->fetchColumn();$q=$pdo->prepare("INSERT IGNORE INTO talk_queues(department_id,name,slug,status,auto_assign_after_seconds) VALUES(:department_id,'Atendimento geral','atendimento-geral','active',30)");$q->execute(['department_id'=>$departmentId]);$queueId=(int)$pdo->query("SELECT id FROM talk_queues WHERE slug='atendimento-geral'")->fetchColumn();$pdo->prepare("INSERT INTO talk_queue_members(queue_id,user_id,role,capacity,status) VALUES(:queue_id,:user_id,'agent',5,'active') ON DUPLICATE KEY UPDATE status='active'")->execute(['queue_id'=>$queueId,'user_id'=>$actorId]);$external='sim:'.bin2hex(random_bytes(6));$c=$pdo->prepare("INSERT INTO talk_contacts(name,phone,external_id,channel,metadata) VALUES('Cliente de simulação','SIM-0001',:external_id,'simulation',:metadata)");$c->execute(['external_id'=>$external,'metadata'=>json_encode(['simulation'=>true],JSON_THROW_ON_ERROR)]);$contactId=(int)$pdo->lastInsertId();$cv=$pdo->prepare("INSERT INTO talk_conversations(contact_id,channel,external_id,status,last_message_at) VALUES(:contact_id,'simulation',:external_id,'open',NOW())");$cv->execute(['contact_id'=>$contactId,'external_id'=>$external.':conversation']);$conversationId=(int)$pdo->lastInsertId();$protocol='SIM-'.date('Ymd').'-'.strtoupper(bin2hex(random_bytes(3)));$t=$pdo->prepare("INSERT INTO talk_tickets(protocol,conversation_id,queue_id,status,priority,subject,source,queued_at) VALUES(:protocol,:conversation_id,:queue_id,'queued','normal','Atendimento de simulação','simulation',NOW())");$t->execute(['protocol'=>$protocol,'conversation_id'=>$conversationId,'queue_id'=>$queueId]);$ticketId=(int)$pdo->lastInsertId();$pdo->prepare("INSERT INTO talk_messages(conversation_id,ticket_id,sender_type,direction,type,body,sent_at,metadata) VALUES(:conversation_id,:ticket_id,'contact','inbound','text','Olá, preciso de ajuda com meu atendimento.',NOW(),:metadata)")->execute(['conversation_id'=>$conversationId,'ticket_id'=>$ticketId,'metadata'=>json_encode(['simulation'=>true],JSON_THROW_ON_ERROR)]);$this->event($ticketId,$actorId,'ticket.created',['source'=>'simulation']);$pdo->commit();return $ticketId;}catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;} }
    public function ticketTransferOptions(int $ticketId,int $userId): array { if(!$this->canOperateTicket($ticketId,$userId))return ['queues'=>[],'eligible_users'=>[]];$pdo=Connection::getInstance();$s=$pdo->prepare("SELECT queue_id FROM talk_tickets WHERE id=:id AND tenant_id=:tenant_id LIMIT 1");$s->execute(['id'=>$ticketId,'tenant_id'=>$this->tenantId($userId)]);$queueId=$s->fetchColumn();if($this->canManage($userId))return ['queues'=>$this->queues(),'eligible_users'=>$this->eligibleUsers($queueId!==false&&$queueId!==null?(int)$queueId:null)];$q=$pdo->prepare("SELECT q.id,q.name,q.slug,q.status,q.auto_assign_after_seconds FROM talk_queues q INNER JOIN talk_queue_members qm ON qm.queue_id=q.id AND qm.user_id=:user_id AND qm.status='active' WHERE q.tenant_id=:tenant_id AND q.status='active' ORDER BY q.name");$q->execute(['user_id'=>$userId,'tenant_id'=>$this->tenantId($userId)]);$queues=$q->fetchAll(PDO::FETCH_ASSOC);$users=[];if($queueId!==false&&$queueId!==null){$users=$this->eligibleUsers((int)$queueId);}return ['queues'=>$queues,'eligible_users'=>$users]; }

    public function ticket(int $ticketId,?int $userId=null): ?array { $pdo=Connection::getInstance();$s=$pdo->prepare("SELECT t.*,c.name contact_name,c.phone contact_phone,cv.channel,q.name queue_name,u.name assigned_name FROM talk_tickets t INNER JOIN talk_conversations cv ON cv.id=t.conversation_id INNER JOIN talk_contacts c ON c.id=cv.contact_id LEFT JOIN talk_queues q ON q.id=t.queue_id LEFT JOIN users u ON u.id=t.assigned_user_id WHERE t.id=:id".($userId!==null?" AND t.tenant_id=:tenant_id":"")." LIMIT 1");$params=['id'=>$ticketId];if($userId!==null)$params['tenant_id']=$this->tenantId($userId);$s->execute($params);$ticket=$s->fetch(PDO::FETCH_ASSOC);if(!$ticket)return null;$m=$pdo->prepare("SELECT m.*,u.name sender_name FROM talk_messages m LEFT JOIN users u ON u.id=m.sender_user_id WHERE m.ticket_id=:id ORDER BY m.sent_at,m.id");$m->execute(['id'=>$ticketId]);$e=$pdo->prepare("SELECT e.*,u.name user_name FROM talk_events e LEFT JOIN users u ON u.id=e.user_id WHERE e.ticket_id=:id ORDER BY e.created_at DESC,e.id DESC LIMIT 50");$e->execute(['id'=>$ticketId]);$ticket['messages']=$m->fetchAll(PDO::FETCH_ASSOC);$ticket['events']=$e->fetchAll(PDO::FETCH_ASSOC);$ticket['notes']=$this->notes($ticketId);return $ticket; }
    public function sendSimulationMessage(int $ticketId,int $userId,string $body): void { $body=trim($body);if($body==='')return;$ticket=$this->ticket($ticketId);if($ticket===null||$ticket['source']!=='simulation'||(int)($ticket['assigned_user_id']??0)!==$userId)throw new \RuntimeException('Atendimento de simulação indisponível para este usuário.');$pdo=Connection::getInstance();$pdo->prepare("INSERT INTO talk_messages(conversation_id,ticket_id,sender_type,sender_user_id,direction,type,body,sent_at,metadata) VALUES(:conversation_id,:ticket_id,'user',:user_id,'outbound','text',:body,NOW(),:metadata)")->execute(['conversation_id'=>$ticket['conversation_id'],'ticket_id'=>$ticketId,'user_id'=>$userId,'body'=>$body,'metadata'=>json_encode(['simulation'=>true],JSON_THROW_ON_ERROR)]);$pdo->prepare("UPDATE talk_tickets SET first_response_at=COALESCE(first_response_at,NOW()),last_activity_at=NOW(),updated_at=NOW() WHERE id=:id")->execute(['id'=>$ticketId]);$pdo->prepare("UPDATE talk_conversations SET last_message_at=NOW(),updated_at=NOW() WHERE id=:id")->execute(['id'=>$ticket['conversation_id']]); }
    public function ticketTags(int $ticketId): array { $s=Connection::getInstance()->prepare("SELECT tg.id,tg.name,tg.slug FROM talk_ticket_tags tt INNER JOIN talk_tags tg ON tg.id=tt.tag_id WHERE tt.ticket_id=:id ORDER BY tg.name");$s->execute(['id'=>$ticketId]);return $s->fetchAll(PDO::FETCH_ASSOC); }
    public function availableTags(int $userId): array { $s=Connection::getInstance()->prepare("SELECT id,name,slug FROM talk_tags WHERE tenant_id=:tenant_id ORDER BY name LIMIT 100");$s->execute(['tenant_id'=>$this->tenantId($userId)]);return $s->fetchAll(PDO::FETCH_ASSOC); }
    public function setTicketTags(int $ticketId,int $userId,array $tagIds): void { if(!$this->canOperateTicket($ticketId,$userId))throw new \RuntimeException('Você não pode alterar este atendimento.');$ids=array_values(array_unique(array_filter(array_map('intval',$tagIds),fn($id)=>$id>0)));$pdo=Connection::getInstance();$pdo->beginTransaction();try{$pdo->prepare("DELETE FROM talk_ticket_tags WHERE ticket_id=:id")->execute(['id'=>$ticketId]);if($ids!==[]){$tenantId=$this->tenantId($userId);$valid=$pdo->prepare("SELECT id FROM talk_tags WHERE tenant_id=? AND id IN (".implode(',',array_fill(0,count($ids),'?')).")");$valid->execute(array_merge([$tenantId],$ids));$add=$pdo->prepare("INSERT INTO talk_ticket_tags(ticket_id,tag_id) VALUES(:ticket_id,:tag_id)");foreach($valid->fetchAll(PDO::FETCH_COLUMN) as $tagId)$add->execute(['ticket_id'=>$ticketId,'tag_id'=>(int)$tagId]);}$pdo->commit();$this->event($ticketId,$userId,'ticket.tags_updated',['tag_ids'=>$ids]);}catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;} }
    public function contactTicketHistory(int $ticketId,int $userId): array { $pdo=Connection::getInstance();$tenantId=$this->tenantId($userId);$base=$pdo->prepare("SELECT cv.contact_id FROM talk_tickets t INNER JOIN talk_conversations cv ON cv.id=t.conversation_id WHERE t.id=:id AND t.tenant_id=:tenant_id");$base->execute(['id'=>$ticketId,'tenant_id'=>$tenantId]);$contactId=(int)$base->fetchColumn();if($contactId===0)return [];$sql="SELECT t.id,t.protocol,t.subject,t.status,t.priority,t.created_at,t.closed_at FROM talk_tickets t INNER JOIN talk_conversations cv ON cv.id=t.conversation_id LEFT JOIN talk_queue_members qm ON qm.queue_id=t.queue_id AND qm.user_id=:user_id AND qm.status='active' WHERE t.tenant_id=:tenant_id AND cv.contact_id=:contact_id";if(!$this->canManage($userId))$sql.=" AND (t.assigned_user_id=:user_id OR (t.status='queued' AND qm.user_id IS NOT NULL))";$sql.=" ORDER BY t.created_at DESC,t.id DESC LIMIT 10";$s=$pdo->prepare($sql);$s->execute(['user_id'=>$userId,'tenant_id'=>$tenantId,'contact_id'=>$contactId]);return $s->fetchAll(PDO::FETCH_ASSOC); }

    public function myTickets(int $userId): array { $s=Connection::getInstance()->prepare("SELECT t.id,t.protocol,t.subject,t.priority,t.status,t.updated_at,t.sla_due_at,c.name contact_name,c.phone contact_phone,q.name queue_name,u.name assigned_name FROM talk_tickets t INNER JOIN talk_conversations cv ON cv.id=t.conversation_id INNER JOIN talk_contacts c ON c.id=cv.contact_id LEFT JOIN talk_queues q ON q.id=t.queue_id LEFT JOIN users u ON u.id=t.assigned_user_id WHERE t.tenant_id=:tenant_id AND t.assigned_user_id=:user_id AND t.status IN ('assigned','open') ORDER BY t.updated_at DESC LIMIT 100");$s->execute(['tenant_id'=>$this->tenantId($userId),'user_id'=>$userId]);return $s->fetchAll(PDO::FETCH_ASSOC); }
    public function history(): array { return Connection::getInstance()->query("SELECT t.id,t.protocol,t.subject,t.priority,t.status,t.closed_at,t.updated_at,c.name contact_name,q.name queue_name,u.name assigned_name FROM talk_tickets t INNER JOIN talk_conversations cv ON cv.id=t.conversation_id INNER JOIN talk_contacts c ON c.id=cv.contact_id LEFT JOIN talk_queues q ON q.id=t.queue_id LEFT JOIN users u ON u.id=t.assigned_user_id WHERE t.status='closed' ORDER BY t.closed_at DESC,t.id DESC LIMIT 100")->fetchAll(PDO::FETCH_ASSOC); }
    public function transfers(): array { return Connection::getInstance()->query("SELECT tr.*,t.protocol,fu.name from_user,tu.name to_user,fq.name from_queue,tq.name to_queue,cu.name created_by_name FROM talk_transfers tr INNER JOIN talk_tickets t ON t.id=tr.ticket_id LEFT JOIN users fu ON fu.id=tr.from_user_id LEFT JOIN users tu ON tu.id=tr.to_user_id LEFT JOIN talk_queues fq ON fq.id=tr.from_queue_id LEFT JOIN talk_queues tq ON tq.id=tr.to_queue_id LEFT JOIN users cu ON cu.id=tr.created_by ORDER BY tr.created_at DESC,tr.id DESC LIMIT 100")->fetchAll(PDO::FETCH_ASSOC); }
    public function queues(?int $userId=null): array { $pdo=Connection::getInstance();if($userId===null)return $pdo->query("SELECT q.id,q.name,q.slug,q.status,q.auto_assign_after_seconds,d.name department_name,COUNT(qm.user_id) members FROM talk_queues q LEFT JOIN talk_departments d ON d.id=q.department_id LEFT JOIN talk_queue_members qm ON qm.queue_id=q.id AND qm.status='active' GROUP BY q.id,d.name ORDER BY q.name")->fetchAll(PDO::FETCH_ASSOC);$s=$pdo->prepare("SELECT q.id,q.name,q.slug,q.status,q.auto_assign_after_seconds,d.name department_name,COUNT(qm.user_id) members FROM talk_queues q LEFT JOIN talk_departments d ON d.id=q.department_id LEFT JOIN talk_queue_members qm ON qm.queue_id=q.id AND qm.status='active' WHERE q.tenant_id=:tenant_id GROUP BY q.id,d.name ORDER BY q.name");$s->execute(['tenant_id'=>$this->tenantId($userId)]);return $s->fetchAll(PDO::FETCH_ASSOC); }
    public function eligibleUsers(?int $queueId=null,?int $userId=null): array { $pdo=Connection::getInstance();if($queueId===null){if($userId===null)return [];$s=$pdo->prepare("SELECT u.id,u.name,u.email,u.role,u.status FROM talk_tenant_users tu INNER JOIN users u ON u.id=tu.user_id WHERE tu.tenant_id=:tenant_id AND tu.status='active' AND u.status='active' ORDER BY u.name");$s->execute(['tenant_id'=>$this->tenantId($userId)]);return $s->fetchAll(PDO::FETCH_ASSOC);}$sql="SELECT u.id,u.name,u.email,qm.role,qm.capacity FROM talk_queue_members qm INNER JOIN talk_queues q ON q.id=qm.queue_id INNER JOIN users u ON u.id=qm.user_id WHERE qm.queue_id=:queue_id AND qm.status='active' AND q.status='active' AND u.status='active'";$params=['queue_id'=>$queueId];if($userId!==null){$sql.=" AND q.tenant_id=:tenant_id";$params['tenant_id']=$this->tenantId($userId);}$sql.=" ORDER BY u.name";$s=$pdo->prepare($sql);$s->execute($params);return $s->fetchAll(PDO::FETCH_ASSOC); }
    public function addNote(int $ticketId,int $userId,string $body): void { if(!$this->canOperateTicket($ticketId,$userId))throw new \RuntimeException('Você não pode alterar este atendimento.'); $body=trim($body);if($body==='')return;Connection::getInstance()->prepare("INSERT INTO talk_notes(ticket_id,user_id,body) VALUES(:ticket_id,:user_id,:body)")->execute(['ticket_id'=>$ticketId,'user_id'=>$userId,'body'=>$body]);$this->event($ticketId,$userId,'ticket.note_added',['body'=>$body]); }
    public function notes(int $ticketId): array { $s=Connection::getInstance()->prepare("SELECT n.*,u.name user_name FROM talk_notes n LEFT JOIN users u ON u.id=n.user_id WHERE n.ticket_id=:id ORDER BY n.created_at DESC,n.id DESC");$s->execute(['id'=>$ticketId]);return $s->fetchAll(PDO::FETCH_ASSOC); }
    public function returnToQueue(int $ticketId,int $userId): void { if(!$this->canOperateTicket($ticketId,$userId))throw new \RuntimeException('Você não pode alterar este atendimento.'); $pdo=Connection::getInstance();$s=$pdo->prepare("SELECT assigned_user_id FROM talk_tickets WHERE id=:id AND status IN ('assigned','open')");$s->execute(['id'=>$ticketId]);$previous=(int)$s->fetchColumn();$u=$pdo->prepare("UPDATE talk_tickets SET assigned_user_id=NULL,status='queued',queued_at=NOW(),assigned_at=NULL,updated_at=NOW() WHERE id=:id AND status IN ('assigned','open')");$u->execute(['id'=>$ticketId]);if($u->rowCount()!==1)throw new \RuntimeException('Atendimento não pode retornar para a fila.');$this->event($ticketId,$userId,'ticket.returned_to_queue',[]);if($previous>0&&$previous!==$userId)$this->notifications()->notifyUser($previous,$ticketId,'ticket.returned_to_queue','Atendimento retornou para a fila','Um atendimento sob sua responsabilidade foi devolvido à fila.'); }
    public function close(int $ticketId,int $userId): void { if(!$this->canOperateTicket($ticketId,$userId))throw new \RuntimeException('Você não pode alterar este atendimento.'); $s=Connection::getInstance()->prepare("UPDATE talk_tickets SET status='closed',closed_at=NOW(),closed_by=:user_id,updated_at=NOW() WHERE id=:id AND status<>'closed'");$s->execute(['user_id'=>$userId,'id'=>$ticketId]);if($s->rowCount()!==1)throw new \RuntimeException('Atendimento já finalizado ou indisponível.');$this->event($ticketId,$userId,'ticket.closed',[]); }
    public function reopen(int $ticketId,int $userId): void { if(!$this->canManage($userId))throw new \RuntimeException('Somente supervisores ou administradores podem reabrir atendimentos.'); $s=Connection::getInstance()->prepare("UPDATE talk_tickets SET status='queued',assigned_user_id=NULL,queued_at=NOW(),assigned_at=NULL,closed_at=NULL,closed_by=NULL,updated_at=NOW() WHERE id=:id AND status='closed'");$s->execute(['id'=>$ticketId]);if($s->rowCount()!==1)throw new \RuntimeException('Atendimento não pode ser reaberto.');$this->event($ticketId,$userId,'ticket.reopened',[]); }
    public function transfer(int $ticketId,int $userId,?int $toUserId,?int $toQueueId,string $reason): void { if(!$this->canOperateTicket($ticketId,$userId))throw new \RuntimeException('Você não pode alterar este atendimento.'); if($toUserId===null&&$toQueueId===null)throw new \RuntimeException('Selecione um atendente ou uma fila.');$pdo=Connection::getInstance();$pdo->beginTransaction();try{$tenantId=$this->tenantId($userId);$s=$pdo->prepare("SELECT assigned_user_id,queue_id,status,tenant_id FROM talk_tickets WHERE id=:id AND tenant_id=:tenant_id FOR UPDATE");$s->execute(['id'=>$ticketId,'tenant_id'=>$tenantId]);$t=$s->fetch(PDO::FETCH_ASSOC);if(!$t||!in_array($t['status'],['assigned','open'],true))throw new \RuntimeException('Atendimento indisponível para transferência.');$targetQueue=$toQueueId??($t['queue_id']!==null?(int)$t['queue_id']:null);if($targetQueue===null)throw new \RuntimeException('Selecione uma fila válida para a transferência.');$q=$pdo->prepare("SELECT COUNT(*) FROM talk_queues WHERE id=:queue_id AND tenant_id=:tenant_id AND status='active'");$q->execute(['queue_id'=>$targetQueue,'tenant_id'=>$tenantId]);if((int)$q->fetchColumn()===0)throw new \RuntimeException('Fila fora da administradora atual ou indisponível.');if(!$this->canManage($userId)){$actorQueue=$pdo->prepare("SELECT COUNT(*) FROM talk_queue_members WHERE queue_id=:queue_id AND user_id=:user_id AND status='active'");$actorQueue->execute(['queue_id'=>$targetQueue,'user_id'=>$userId]);if((int)$actorQueue->fetchColumn()===0)throw new \RuntimeException('Você não pode transferir para esta fila.');}if($toUserId!==null){$e=$pdo->prepare("SELECT COUNT(*) FROM talk_queue_members WHERE queue_id=:queue_id AND user_id=:user_id AND status='active'");$e->execute(['queue_id'=>$targetQueue,'user_id'=>$toUserId]);if((int)$e->fetchColumn()===0)throw new \RuntimeException('Atendente não pertence à fila selecionada.');}$newStatus=$toUserId!==null?'assigned':'queued';$pdo->prepare("UPDATE talk_tickets SET queue_id=:queue_id,assigned_user_id=:assigned,status=:status,queued_at=IF(:status='queued',NOW(),queued_at),assigned_at=IF(:status='assigned',NOW(),NULL),updated_at=NOW() WHERE id=:id")->execute(['queue_id'=>$targetQueue,'assigned'=>$toUserId,'status'=>$newStatus,'id'=>$ticketId]);$pdo->prepare("INSERT INTO talk_transfers(ticket_id,from_user_id,from_queue_id,to_user_id,to_queue_id,reason,status,created_by) VALUES(:ticket_id,:from_user,:from_queue,:to_user,:to_queue,:reason,'completed',:created_by)")->execute(['ticket_id'=>$ticketId,'from_user'=>$t['assigned_user_id'],'from_queue'=>$t['queue_id'],'to_user'=>$toUserId,'to_queue'=>$targetQueue,'reason'=>trim($reason),'created_by'=>$userId]);$pdo->commit();$this->event($ticketId,$userId,'ticket.transferred',['to_user_id'=>$toUserId,'to_queue_id'=>$targetQueue]);if($toUserId!==null&&$toUserId!==$userId)$this->notifications()->notifyUser($toUserId,$ticketId,'ticket.transferred','Novo atendimento transferido para você',trim($reason)!==''?trim($reason):'Abra o atendimento para continuar a conversa.',['from_user_id'=>$t['assigned_user_id'],'queue_id'=>$targetQueue]);if($t['assigned_user_id']!==null&&(int)$t['assigned_user_id']!==$userId&&(int)$t['assigned_user_id']!==$toUserId)$this->notifications()->notifyUser((int)$t['assigned_user_id'],$ticketId,'ticket.transferred_away','Atendimento transferido','O atendimento deixou sua responsabilidade.');}catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;} }
    public function autoAssign(): int { $settings=$this->settings();if(($settings['auto_assign.enabled']??'1')!=='1')return 0;$pdo=Connection::getInstance();$tickets=$pdo->query("SELECT id,queue_id FROM talk_tickets WHERE status='queued' AND queue_id IS NOT NULL AND TIMESTAMPDIFF(SECOND,COALESCE(queued_at,created_at),NOW())>=COALESCE((SELECT auto_assign_after_seconds FROM talk_queues q WHERE q.id=talk_tickets.queue_id),30) ORDER BY COALESCE(queued_at,created_at) LIMIT 50")->fetchAll(PDO::FETCH_ASSOC);$assigned=0;foreach($tickets as $ticket){$s=$pdo->prepare("SELECT qm.user_id FROM talk_queue_members qm INNER JOIN users u ON u.id=qm.user_id LEFT JOIN talk_presence p ON p.user_id=u.id LEFT JOIN talk_user_settings tus ON tus.user_id=u.id LEFT JOIN (SELECT assigned_user_id,COUNT(*) active FROM talk_tickets WHERE status IN ('assigned','open') GROUP BY assigned_user_id) a ON a.assigned_user_id=u.id WHERE qm.queue_id=:queue_id AND qm.status='active' AND u.status='active' AND p.status='online' AND p.last_seen_at>=DATE_SUB(NOW(),INTERVAL 5 MINUTE) AND COALESCE(a.active,0)<LEAST(qm.capacity,COALESCE(tus.max_active_tickets,qm.capacity)) ORDER BY COALESCE(a.active,0),p.last_seen_at DESC,qm.user_id LIMIT 1");$s->execute(['queue_id'=>$ticket['queue_id']]);$uid=(int)$s->fetchColumn();if($uid>0&&$this->claim((int)$ticket['id'],$uid)){$this->notifications()->notifyUser($uid,(int)$ticket['id'],'ticket.auto_assigned','Novo atendimento atribuído','Um atendimento da sua fila foi atribuído automaticamente a você.');$assigned++;}}return $assigned; }
    public function updatePresence(int $userId,string $status): void { if(!in_array($status,['online','away','offline'],true))$status='offline';Connection::getInstance()->prepare("INSERT INTO talk_presence(user_id,status,last_seen_at) VALUES(:user_id,:status,NOW()) ON DUPLICATE KEY UPDATE status=VALUES(status),last_seen_at=NOW()")->execute(['user_id'=>$userId,'status'=>$status]); }
    public function usersWithPresence(): array { return Connection::getInstance()->query("SELECT u.id,u.name,u.email,u.role,u.status,COALESCE(tus.talk_role,IF(u.role='admin','admin','agent')) talk_role,COALESCE(tus.max_active_tickets,5) max_active_tickets,COALESCE(p.status,'offline') presence,p.last_seen_at,(SELECT COUNT(*) FROM talk_tickets t WHERE t.assigned_user_id=u.id AND t.status IN ('assigned','open')) active_tickets FROM users u LEFT JOIN talk_user_settings tus ON tus.user_id=u.id LEFT JOIN talk_presence p ON p.user_id=u.id WHERE u.status='active' ORDER BY u.name")->fetchAll(PDO::FETCH_ASSOC); }
    public function reports(int $userId): array { $pdo=Connection::getInstance();$tenantId=$this->tenantId($userId);$count=$pdo->prepare("SELECT status,COUNT(*) total FROM talk_tickets WHERE tenant_id=:tenant_id GROUP BY status");$count->execute(['tenant_id'=>$tenantId]);$totals=['total'=>0,'queued'=>0,'active'=>0,'closed'=>0];foreach($count->fetchAll(PDO::FETCH_ASSOC) as $row){$n=(int)$row['total'];$totals['total']+=$n;if($row['status']==='queued')$totals['queued']+=$n;elseif(in_array($row['status'],['assigned','open'],true))$totals['active']+=$n;elseif($row['status']==='closed')$totals['closed']+=$n;}$q=$pdo->prepare("SELECT COALESCE(q.name,'Sem fila') label,COUNT(t.id) total FROM talk_tickets t LEFT JOIN talk_queues q ON q.id=t.queue_id WHERE t.tenant_id=:tenant_id GROUP BY q.id,q.name ORDER BY total DESC");$q->execute(['tenant_id'=>$tenantId]);$totals['by_queue']=$q->fetchAll(PDO::FETCH_ASSOC);return $totals; }
    public function settings(?int $userId=null): array { $pdo=Connection::getInstance();if($userId===null)$rows=$pdo->query("SELECT setting_key,setting_value FROM talk_settings WHERE tenant_id=1 ORDER BY setting_key")->fetchAll(PDO::FETCH_ASSOC);else{$s=$pdo->prepare("SELECT setting_key,setting_value FROM talk_settings WHERE tenant_id=:tenant_id ORDER BY setting_key");$s->execute(['tenant_id'=>$this->tenantId($userId)]);$rows=$s->fetchAll(PDO::FETCH_ASSOC);}$out=[];foreach($rows as $row)$out[$row['setting_key']]=$row['setting_value'];return $out; }
    public function saveSettings(array $values,int $userId): void { $allowed=['jack.enabled','jack.wait_seconds','jack.transfer_summary','auto_assign.enabled','auto_assign.default_seconds'];$s=Connection::getInstance()->prepare("INSERT INTO talk_settings(tenant_id,setting_key,setting_value,updated_by) VALUES(:tenant_id,:key,:value,:user_id) ON DUPLICATE KEY UPDATE setting_value=VALUES(setting_value),updated_by=VALUES(updated_by)");foreach($allowed as $key)if(array_key_exists($key,$values))$s->execute(['tenant_id'=>$this->tenantId($userId),'key'=>$key,'value'=>(string)$values[$key],'user_id'=>$userId]); }
    public function jackInteractions(int $userId): array { $s=Connection::getInstance()->prepare("SELECT ji.*,t.protocol,c.name contact_name FROM talk_jack_interactions ji INNER JOIN talk_tickets t ON t.id=ji.ticket_id INNER JOIN talk_conversations cv ON cv.id=t.conversation_id INNER JOIN talk_contacts c ON c.id=cv.contact_id WHERE t.tenant_id=:tenant_id ORDER BY ji.created_at DESC,ji.id DESC LIMIT 100");$s->execute(['tenant_id'=>$this->tenantId($userId)]);return $s->fetchAll(PDO::FETCH_ASSOC); }
    public function channels(int $userId): array { $s=Connection::getInstance()->prepare("SELECT id,type,name,status,last_connected_at,created_at,updated_at FROM talk_channels WHERE tenant_id=:tenant_id ORDER BY id");$s->execute(['tenant_id'=>$this->tenantId($userId)]);return $s->fetchAll(PDO::FETCH_ASSOC); }
    private function event(int $ticketId,?int $userId,string $type,array $payload): void { $s=Connection::getInstance()->prepare("INSERT INTO talk_events(ticket_id,user_id,actor_type,event_type,payload) VALUES(:ticket_id,:user_id,:actor_type,:event_type,:payload)");$s->execute(['ticket_id'=>$ticketId,'user_id'=>$userId,'actor_type'=>$userId===null?'system':'user','event_type'=>$type,'payload'=>json_encode($payload,JSON_THROW_ON_ERROR)]); }
    public function syncState(int $userId): array
    {
        $pdo=Connection::getInstance();$tenantId=$this->tenantId($userId);
        if($this->canManage($userId)){
            $ticketSql="SELECT COALESCE(UNIX_TIMESTAMP(MAX(updated_at)),0) FROM talk_tickets WHERE tenant_id=:tenant_id";
            $messageSql="SELECT COALESCE(UNIX_TIMESTAMP(MAX(m.created_at)),0) FROM talk_messages m INNER JOIN talk_tickets t ON t.id=m.ticket_id WHERE t.tenant_id=:tenant_id";
            $params=['tenant_id'=>$tenantId];
        }else{
            $ticketSql="SELECT COALESCE(UNIX_TIMESTAMP(MAX(t.updated_at)),0) FROM talk_tickets t LEFT JOIN talk_queue_members qm ON qm.queue_id=t.queue_id AND qm.user_id=:user_id AND qm.status='active' WHERE t.tenant_id=:tenant_id AND (t.assigned_user_id=:user_id OR (t.status='queued' AND qm.user_id IS NOT NULL))";
            $messageSql="SELECT COALESCE(UNIX_TIMESTAMP(MAX(m.created_at)),0) FROM talk_messages m INNER JOIN talk_tickets t ON t.id=m.ticket_id LEFT JOIN talk_queue_members qm ON qm.queue_id=t.queue_id AND qm.user_id=:user_id AND qm.status='active' WHERE t.tenant_id=:tenant_id AND (t.assigned_user_id=:user_id OR (t.status='queued' AND qm.user_id IS NOT NULL))";
            $params=['tenant_id'=>$tenantId,'user_id'=>$userId];
        }
        $s=$pdo->prepare($ticketSql);$s->execute($params);$tickets=(int)$s->fetchColumn();
        $s=$pdo->prepare($messageSql);$s->execute($params);$messages=(int)$s->fetchColumn();
        return ['revision'=>max($tickets,$messages),'server_time'=>time(),'queue_count'=>count($this->queueForUser($userId)),'mine_count'=>count($this->myTickets($userId))];
    }
    public function conversations(int $userId): array { $s=Connection::getInstance()->prepare("SELECT cv.id,cv.channel,cv.status,cv.last_message_at,c.name contact_name,c.phone,t.protocol,t.status ticket_status,q.name queue_name,u.name assigned_name FROM talk_conversations cv INNER JOIN talk_contacts c ON c.id=cv.contact_id LEFT JOIN talk_tickets t ON t.id=(SELECT tt.id FROM talk_tickets tt WHERE tt.conversation_id=cv.id AND tt.tenant_id=:tenant_id ORDER BY tt.id DESC LIMIT 1) LEFT JOIN talk_queues q ON q.id=t.queue_id LEFT JOIN users u ON u.id=t.assigned_user_id WHERE cv.tenant_id=:tenant_id ORDER BY COALESCE(cv.last_message_at,cv.created_at) DESC LIMIT 100");$s->execute(['tenant_id'=>$this->tenantId($userId)]);return $s->fetchAll(PDO::FETCH_ASSOC); }
    public function contacts(int $userId): array { $s=Connection::getInstance()->prepare("SELECT id,name,phone,email,channel,created_at,updated_at FROM talk_contacts WHERE tenant_id=:tenant_id ORDER BY updated_at DESC,id DESC LIMIT 100");$s->execute(['tenant_id'=>$this->tenantId($userId)]);return $s->fetchAll(PDO::FETCH_ASSOC); }
    private function count(PDO $pdo,string $sql): int { return (int)$pdo->query($sql)->fetchColumn(); }
